</div>
<div>
<p class="font-title-md text-title-md text-on-surface text-[14px]">Kendala pada gerbang?</p>
<p class="font-body-sm text-body-sm text-on-surface-variant">Hubungi Petugas Sirkulasi Meja Depan</p>
</div>
</div>
<button class="px-space-sm py-1 rounded-xl bg-surface-container-lowest font-label-sm text-label-sm text-primary shadow-sm hover:bg-surface-container transition-colors">
      Bantuan
    </button>
</div>
<!-- Primary & Secondary CTA Action Footer -->
<div class="flex flex-col gap-space-sm mt-space-xs">
