<!-- Micro-interactions: Tab Switcher, Timer Simulation, Wallet Feedback -->
<script>
  (function() {
    const tabBarcode = document.getElementById('tab-barcode');
    const tabQrcode = document.getElementById('tab-qrcode');
    const viewBarcode = document.getElementById('view-barcode');
    const viewQrcode = document.getElementById('view-qrcode');
    const timerDisplay = document.getElementById('pass-timer');
    const btnSavePass = document.getElementById('btn-save-pass');
    const btnClose = document.getElementById('btn-close');
    const btnToCirculation = document.getElementById('btn-to-circulation');
    const btnToCatalog = document.getElementById('btn-to-catalog');

    // Tab switching interaction
    if (tabBarcode && tabQrcode && viewBarcode && viewQrcode) {
      tabBarcode.addEventListener('click', function() {
        tabBarcode.className = 'flex-1 py-1.5 rounded-lg text-label-md font-label-md text-center transition-all bg-surface-container-lowest text-on-surface shadow-sm flex items-center justify-center gap-1';
        tabQrcode.className = 'flex-1 py-1.5 rounded-lg text-label-md font-label-md text-center transition-all text-on-surface-variant hover:text-on-surface flex items-center justify-center gap-1';
        viewBarcode.classList.remove('hidden');
        viewBarcode.classList.add('flex');
        viewQrcode.classList.add('hidden');
        viewQrcode.classList.remove('flex');
      });

      tabQrcode.addEventListener('click', function() {
        tabQrcode.className = 'flex-1 py-1.5 rounded-lg text-label-md font-label-md text-center transition-all bg-surface-container-lowest text-on-surface shadow-sm flex items-center justify-center gap-1';
        tabBarcode.className = 'flex-1 py-1.5 rounded-lg text-label-md font-label-md text-center transition-all text-on-surface-variant hover:text-on-surface flex items-center justify-center gap-1';
        viewQrcode.classList.remove('hidden');
        viewQrcode.classList.add('flex');
        viewBarcode.classList.add('hidden');
        viewBarcode.classList.remove('flex');
      });
    }

    // 15-minute countdown clock
    let totalSeconds = 14 * 60 + 59;
    const interval = setInterval(function() {
      if (!timerDisplay) return;
      if (totalSeconds <= 0) {
        clearInterval(interval);
        timerDisplay.textContent = '00:00';
        return;
      }
      totalSeconds--;
      const mins = Math.floor(totalSeconds / 60);
      const secs = totalSeconds % 60;
      timerDisplay.textContent = 
        (mins < 10 ? '0' : '') + mins + ':' + (secs < 10 ? '0' : '') + secs;
    }, 1000);

    // Save Pass Feedback
    if (btnSavePass) {
      btnSavePass.addEventListener('click', function() {
        const originalText = btnSavePass.innerHTML;
        btnSavePass.innerHTML = '<span class="material-symbols-outlined text-[22px]">check</span><span>Tiket Berhasil Tersimpan!</span>';
        btnSavePass.classList.add('bg-secondary-container', 'text-on-secondary-container');
        btnSavePass.classList.remove('bg-primary-container', 'text-on-primary');
        setTimeout(function() {
          btnSavePass.innerHTML = originalText;
          btnSavePass.classList.remove('bg-secondary-container', 'text-on-secondary-container');
          btnSavePass.classList.add('bg-primary-container', 'text-on-primary');
        }, 2200);
      });
    }

    // Navigation buttons
    if (btnClose) {
      btnClose.addEventListener('click', function() {
        window.location.href = "{{ route('katalog') }}";
      });
    }
    
    if (btnToCatalog) {
      btnToCatalog.addEventListener('click', function() {
        window.location.href = "{{ route('katalog') }}";
      });
    }

    if (btnToCirculation) {
      btnToCirculation.addEventListener('click', function() {
        window.location.href = "{{ route('sirkulasi') }}";
      });
    }
  })();
</script></main><nav class="fixed bottom-0 w-full z-50 pb-safe bg-surface/85 backdrop-blur-xl shadow-[0_-2px_12px_rgba(0,0,0,0.05)]" data-active-classes="bg-primary-container text-on-primary font-bold shadow-[3px_3px_0px_#1c1b20]"><div class="flex items-center justify-around h-16 px-space-xs max-w-md mx-auto"><a class="flex flex-col items-center justify-center min-w-[64px] min-h-[44px] px-space-sm py-space-xs rounded-xl text-on-surface-variant transition-all hover:text-primary" data-path="katalog-buku" href="{{ route('katalog') }}"><span class="material-symbols-outlined text-[22px]">menu_book</span><span class="font-label-sm text-label-sm tracking-tight mt-0.5">Katalog</span></a><a aria-current="page" class="flex flex-col items-center justify-center min-w-[64px] min-h-[44px] px-space-sm py-space-xs rounded-xl transition-all bg-primary-container text-on-primary font-bold shadow-[3px_3px_0px_#1c1b20]" data-path="sirkulasi-peminjaman" href="{{ route('sirkulasi') }}"><span class="material-symbols-outlined text-[22px]">sync_alt</span><span class="font-label-sm text-label-sm tracking-tight mt-0.5">Sirkulasi</span></a><a class="flex flex-col items-center justify-center min-w-[64px] min-h-[44px] px-space-sm py-space-xs rounded-xl text-on-surface-variant transition-all hover:text-primary" data-path="petugas-statistik" href="{{ route('statistik') }}"><span class="material-symbols-outlined text-[22px]">analytics</span><span class="font-label-sm text-label-sm tracking-tight mt-0.5">Statistik</span></a><a class="flex flex-col items-center justify-center min-w-[64px] min-h-[44px] px-space-sm py-space-xs rounded-xl text-on-surface-variant transition-all hover:text-primary" data-path="akun-profil" href="{{ route('akun') }}"><span class="material-symbols-outlined text-[22px]">account_circle</span><span class="font-label-sm text-label-sm tracking-tight mt-0.5">Akun</span></a></div></nav></body></html>
